void rejectsWorkerCountThatIsNotANumber() throws IOException {
    assertRejected("worker.threads=four\n", "worker.threads", "'four'");
}

@Test
void rejectsTimeoutWhenTheUnitIsMissing() throws IOException {
    assertRejected("request.timeout=30\n", "request.timeout", "'30'");
}

@Test
void rejectsValuesBelowTheMinimum() throws IOException {
    assertRejected("worker.threads=0\n", "worker.threads", "minimum of 1");
    assertRejected("queue.capacity=0\n", "queue.capacity", "minimum of 1");
    assertRejected("retry.max-attempts=-1\n", "retry.max-attempts", "minimum of 0");
}

@Test
void rejectsZeroTimeout() throws IOException {
    assertRejected("request.timeout=0s\n", "request.timeout", "more than zero");
}

@Test
void rejectsMetricsFlagThatIsNotABoolean() throws IOException {
    assertRejected("metrics.enabled=yes\n", "metrics.enabled", "'yes'");
}

@Test
void rejectsUpstreamThatIsNotAnAbsoluteUrl() throws IOException {
    assertRejected("upstream.url=not a url\n", "upstream.url", "not a valid URL");
    assertRejected("upstream.url=/just/a/path\n", "upstream.url", "absolute URL");
}

@Test
void rejectsUnknownKeysSoMisspellingsAreNotIgnored() throws IOException {
    assertRejected("worker.thread=8\n", "unknown key 'worker.thread'");
}

@Test
void rejectsMissingFile() {
    Path missing = dir.resolve("absent.properties");

    ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(missing));

    assertTrue(error.getMessage().contains("file not found"), error.getMessage());
}

@Test
void reportsEveryProblemAtOnce() throws IOException {
    Path file = write("worker.threads=four\nmetrics.enabled=maybe\n");

    ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

    String message = error.getMessage();
    assertTrue(message.contains("upstream.url is required"), message);
    assertTrue(message.contains("api.token is required"), message);
    assertTrue(message.contains("worker.threads"), message);
    assertTrue(message.contains("metrics.enabled"), message);
}

private void assertRejected(String extraLines, String... mentions) throws IOException {
    ConfigException error = assertThrows(
            ConfigException.class, () -> ConfigLoader.load(write(REQUIRED + extraLines)));
    for (String mention : mentions) {
        assertTrue(error.getMessage().contains(mention), error.getMessage());
    }
}

private Path write(String content) throws IOException {
    return Files.writeString(dir.resolve("config.properties"), content);
}

